SELECT CASE WHEN cost >= 77 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, DATE_TRUNC('QUARTER', shipped_date) AS quarter_start, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN status = 'LOST' THEN 1 END), 0), 2) AS cost_per_lost, SUM(CASE WHEN status = 'DELIVERED' THEN cost ELSE 0 END) AS delivered_cost, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN status = 'LOST' THEN 1 END), 0), 2) AS cost_per_lost_2 FROM shipments GROUP BY GROUPING SETS ((CASE WHEN cost >= 77 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('QUARTER', shipped_date)), (CASE WHEN cost >= 77 THEN 'PREMIUM' ELSE 'STANDARD' END), ());
